/**
 * Action 06 プロンプトを構築する
 * 
 * 優先度順に整理した朝会資料が完成したことを部長に通知するプロンプトを生成
 * 
 * @param context - アクション実行コンテキスト
 * @returns 部長への通知プロンプト
 */
export function buildAction06Prompt(context: Action06Context): string {
  const {
    morningMeetingMaterial,
    managerContact,
    notificationConfig,
  } = context;

  const issuesSummary = morningMeetingMaterial.prioritizedIssues
    .map(
      (issue) =>
        `[${issue.priority.toUpperCase()}] ${issue.title} (報告者: ${issue.reportedBy})`
    )
    .join("\n");

  const nonSubmittersList = morningMeetingMaterial.nonSubmitters
    .map((person) => `- ${person.memberName} (${person.email})`)
    .join("\n");

  const notificationMethod =
    notificationConfig.method === "both"
      ? "メールとシステム内通知"
      : notificationConfig.method === "email"
        ? "メール"
        : "システム内通知";

  const prompt = `
あなたは朝会報告管理システムの自動通知エージェントです。
優先度順に整理された朝会資料が完成したため、部長に完成通知を送信してください。

【通知対象】
部長名: ${managerContact.managerName}
メールアドレス: ${managerContact.email}

【朝会資料の完成内容】
資料タイトル: ${morningMeetingMaterial.title}
生成完了時刻: ${morningMeetingMaterial.generatedAt}

【優先度別課題一覧】
${issuesSummary}

合計課題数: ${morningMeetingMaterial.prioritizedIssues.length}件

【未提出メンバー】
${nonSubmittersList.length > 0 ? nonSubmittersList : "なし"}

【資料概要】
${morningMeetingMaterial.summary}

【通知方法】
${notificationMethod}を使用して通知してください。

【実行内容】
1. 部長への通知メッセージを作成する
2. 朝会資料へのアクセスリンクまたは添付ファイルを含める
3. 優先度の高い課題について簡潔に説明する
4. 未提出メンバーがいる場合は、その旨を記載する
5. 朝会開始までの確認期間を明記する
6. 通知を送信し、送信完了を記録する

【通知内容の要件】
- 件名は「朝会資料完成通知」とする
- 本文は簡潔で、重要情報を最初に記載する
- 優先度の高い課題は強調表示する
- 資料へのアクセス方法を明確に記載する
- 部長が即座に確認できるような構成にする

通知送信を完了し、以下の情報を返してください：
- 通知送信の成功/失敗
- 送信ステータス
- 通知ID
- 送信時刻
- 通知内容（件名と本文）
- エラーメッセージ（失敗時）
`;

  return prompt;
}
